<?php
namespace CmuLms;
final class Grade extends Model {public static function forStudent(int $id):array{return self::all('SELECT g.*,c.code course_code FROM grades g JOIN courses c ON c.id=g.course_id WHERE g.student_id=? AND g.released=1 AND c.active=1 AND (g.category<>"quiz" OR EXISTS(SELECT 1 FROM exams e WHERE e.course_id=g.course_id AND e.title=g.title AND (SELECT l.action FROM audit_logs l WHERE l.auditable_type="exams" AND l.auditable_id=e.id AND l.action IN ("exam_scores_shown","exam_scores_hidden") ORDER BY l.id DESC LIMIT 1)="exam_scores_shown")) AND EXISTS(SELECT 1 FROM enrollments en WHERE en.course_id=c.id AND en.user_id=g.student_id AND en.status="active") ORDER BY c.code,g.category,g.title',[$id]);}public static function forCourse(int $id):array{return self::all('SELECT g.*,u.name,u.id_number FROM grades g JOIN users u ON u.id=g.student_id WHERE g.course_id=? ORDER BY u.last_name,u.name,g.title',[$id]);}}
